/* eslint-env serviceworker */

/**
 * Tumbaland's service worker.
 *
 * Hand-written rather than generated by vite-plugin-pwa. The shell's asset
 * graph is federated across eight origins and resolved at runtime from
 * config.json, so a build-time precache manifest would list the shell's own
 * chunks and miss every module. Fighting the plugin into that shape costs more
 * than the sixty lines below.
 *
 * It lives on the shell's origin because that is where the app is installed.
 * chat-front is served from chat.tumbaland.eu but *runs* inside this page, so
 * the worker, the push subscription, the notification permission and the badge
 * all belong here rather than in the chat module.
 *
 * Bump CACHE_VERSION to retire the previous caches on the next activation.
 */

const CACHE_VERSION = 'v1';
const SHELL_CACHE = `tumbaland-shell-${CACHE_VERSION}`;
const PUSH_STATE_CACHE = 'tumbaland-push-state';

/**
 * Only what the app needs to paint something offline. Deliberately tiny:
 * hashed assets are cached as they are used, and listing them here would mean
 * regenerating this file on every build.
 */
const SHELL_ASSETS = ['/', '/index.html', '/manifest.webmanifest', '/icon-192.png', '/icon-512.png', '/badge-96.png', '/favicon.svg'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // `addAll` rejects the whole install if any one request fails, which
      // would leave the app with no worker at all over a single missing icon.
      .then((cache) => Promise.allSettled(SHELL_ASSETS.map((asset) => cache.add(asset))))
      // No skipWaiting here: the page asks for it once the person agrees.
      // Swapping the code under a half-typed message is worse than waiting.
      .then(() => undefined)
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys
        .filter((key) => key.startsWith('tumbaland-shell-') && key !== SHELL_CACHE)
        .map((key) => caches.delete(key))))
      .then(() => self.clients.claim())
  );
});

/** The page asks for this after the person accepts the update prompt. */
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

/**
 * Anything that must never be cached.
 *
 * API responses go stale in a way that is invisible and confusing, and signed
 * file URLs carry an expiry in the query string -- a cached one keeps being
 * served after it has expired, so the image breaks and never recovers.
 */
function isUncacheable(url) {
  return (
    url.pathname.startsWith('/api/') ||
    url.pathname === '/config.json' ||
    url.pathname === '/sw.js' ||
    url.searchParams.has('token')
  );
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  // Cross-origin requests are left alone entirely: the federated modules, the
  // APIs and the file service all live elsewhere and manage their own caching.
  if (url.origin !== self.location.origin) return;
  if (isUncacheable(url)) return;

  // A navigation is network-first, so a deploy is picked up on the next visit
  // rather than whenever the cache happens to be evicted. The cached shell is
  // the offline fallback.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(SHELL_CACHE).then((cache) => cache.put('/index.html', copy));
          return response;
        })
        .catch(() => caches.match('/index.html').then((cached) => cached || Response.error()))
    );
    return;
  }

  // Everything else is stale-while-revalidate: instant from cache, refreshed
  // in the background. Safe because these are content-hashed.
  event.respondWith(
    caches.match(request).then((cached) => {
      const network = fetch(request)
        .then((response) => {
          if (response && response.status === 200 && response.type === 'basic') {
            const copy = response.clone();
            caches.open(SHELL_CACHE).then((cache) => cache.put(request, copy));
          }
          return response;
        })
        .catch(() => cached);
      return cached || network;
    })
  );
});

// ─── Push ────────────────────────────────────────────────────────────────────

/**
 * A message arrived while the app was closed or in the background.
 *
 * `userVisibleOnly` was promised at subscribe time, so a notification must be
 * shown for every push or the browser eventually revokes the subscription. The
 * fallback below exists for exactly that reason: an unreadable payload still
 * produces something rather than nothing.
 */
self.addEventListener('push', (event) => {
  let payload = {};
  try {
    const data = event.data ? event.data.json() : {};
    payload = data && typeof data === 'object' ? data : {};
  } catch {
    payload = {};
  }

  const title = payload.title || 'Tumbaland';
  const options = {
    body: payload.body || 'New message',
    icon: '/icon-192.png',
    // The small icon in the Android status bar. Android keeps only its alpha
    // channel and paints it white, so the full-colour app icon -- opaque edge
    // to edge -- came out as a plain white square. This is the two hearts as a
    // white silhouette on transparency.
    badge: '/badge-96.png',
    // Collapses repeat notifications for one conversation into one line
    // instead of ten while a phone is in a pocket.
    tag: payload.tag || 'tumbaland',
    renotify: Boolean(payload.tag),
    data: { url: payload.url || '/chat' },
    // When the message was sent, not when the push arrived: a push held while
    // the browser was closed should not read "now".
    timestamp: typeof payload.sentAt === 'number' ? payload.sentAt : Date.now()
  };
  // A ringing call stays on screen until it is dealt with, and buzzes like one.
  // The server replaces it with "Missed call" under the same tag if nobody
  // answers, and the page closes it once the call is picked up.
  if (payload.kind === 'call') {
    options.requireInteraction = true;
    options.vibrate = [500, 250, 500, 250, 500, 250, 500];
  }

  // A call answered or declined on another device. Every push must show a
  // notification, so this one replaces "Calling you" under the same tag and is
  // closed straight away: the ringing call leaves the lock screen.
  if (payload.kind === 'call-over') {
    event.waitUntil(showAndClose(title, options));
    return;
  }

  // A message push. The push service holds pushes while the browser is closed
  // and hands the backlog over when it starts, so a message read an hour ago
  // on the phone would otherwise pop up the moment the laptop app opens. The
  // server is asked first; anything already read is dropped the same way as a
  // call answered elsewhere.
  event.waitUntil(
    unreadState(payload.conversationId).then(({ fresh, unread }) => {
      if (!fresh) {
        return Promise.all([showAndClose(title, options), typeof unread === 'number' ? setBadge(unread) : undefined]);
      }
      return Promise.all([
        self.registration.showNotification(title, options),
        setBadge(typeof unread === 'number' ? unread : payload.unread)
      ]);
    })
  );
});

/**
 * Shows a notification and takes it straight down again, along with anything
 * already shown under its tag.
 *
 * Every push must show a notification or the browser eventually revokes the
 * subscription, so a push that turns out to be old news still shows one, just
 * silently and only for an instant.
 */
function showAndClose(title, options) {
  return self.registration
    .showNotification(title, { ...options, silent: true, renotify: false, requireInteraction: false })
    .then(() => self.registration.getNotifications({ tag: options.tag }))
    .then((shown) => shown.forEach((notification) => notification.close()));
}

/**
 * The dot on the home-screen icon. Supported on Android and on iOS 16.4+ for
 * an installed app; absent elsewhere, hence the guard. With no count it shows
 * a plain dot.
 */
function setBadge(count) {
  if (!self.navigator.setAppBadge) return Promise.resolve();
  if (count === 0) return self.navigator.clearAppBadge().catch(() => undefined);
  return self.navigator.setAppBadge(typeof count === 'number' ? count : undefined).catch(() => undefined);
}

/**
 * Whether a message push is still unread, and the total unread for the badge.
 *
 * Errs towards showing: offline, signed out, a slow server or a push from an
 * older server without `conversationId` all count as fresh. A missed message
 * is worse than a stale one.
 */
async function unreadState(conversationId) {
  if (!conversationId) return { fresh: true };
  try {
    const stored = await caches.open(PUSH_STATE_CACHE).then((cache) => cache.match('/__push-config'));
    const config = stored ? await stored.json() : null;
    if (!config?.apiUrl) return { fresh: true };

    // `background` keeps this from counting as the person being online.
    const response = await fetch(`${config.apiUrl}/api/chat/unread?background=1`, {
      credentials: 'include',
      signal: AbortSignal.timeout(5000)
    });
    if (!response.ok) return { fresh: true };
    const data = (await response.json())?.data;
    const count = data?.conversations?.[conversationId];
    return {
      fresh: typeof count === 'number' ? count > 0 : true,
      unread: typeof data?.unread === 'number' ? data.unread : undefined
    };
  } catch {
    return { fresh: true };
  }
}

/**
 * Opening a notification.
 *
 * Focuses a window that is already on the right page instead of opening a
 * second one, which is what makes tapping a notification feel like returning
 * to the app rather than launching it again.
 */
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  let target = new URL('/chat', self.location.origin);
  try {
    const requested = new URL(event.notification.data?.url || '/chat', self.location.origin);
    if (requested.origin === self.location.origin) target = requested;
  } catch { /* An invalid target still opens chat. */ }

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(async (clients) => {
      for (const client of clients) {
        if (new URL(client.url).origin === self.location.origin && 'focus' in client) {
          try {
            // Focus first: the permission to raise a window only lasts briefly
            // after the tap, and must not be spent waiting on a page load.
            const focused = await client.focus();
            // Routed in place rather than reloaded, so a half-typed message and
            // the loaded modules survive. The page's message queue holds this
            // until its listener is attached, so a just-woken page still gets it.
            if (focused.url !== target.href) {
              focused.postMessage({ type: 'NAVIGATE', url: target.pathname + target.search + target.hash });
            }
            return;
          } catch { /* The window may have closed; try the next one. */ }
        }
      }
      return self.clients.openWindow(target.href);
    })
  );
});

/**
 * The push service rotated this browser's endpoint.
 *
 * Without handling this the subscription silently stops working and nobody
 * finds out until a message is not delivered. Re-subscribing here needs the
 * key that was used originally, which is kept in a cache entry because a
 * worker has no other storage that survives a restart.
 */
self.addEventListener('pushsubscriptionchange', (event) => {
  event.waitUntil(
    caches
      .open(PUSH_STATE_CACHE)
      .then((cache) => cache.match('/__push-config'))
      .then((response) => (response ? response.json() : null))
      .then(async (config) => {
        if (!config?.publicKey || !config?.apiUrl) return;
        const subscription = event.newSubscription || await self.registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: config.publicKey
        });
        // Rotation can happen with every window closed. Persist directly,
        // using the same session cookie as the app, rather than only posting
        // to windows that might not exist.
        const response = await fetch(`${config.apiUrl}/api/chat/push/subscriptions`, {
          method: 'POST',
          credentials: 'include',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(subscription.toJSON())
        });
        if (!response.ok) throw new Error('Could not register rotated push subscription');
        return self.clients
          .matchAll({ type: 'window', includeUncontrolled: true })
          .then((clients) =>
            clients.forEach((client) =>
              client.postMessage({ type: 'PUSH_RESUBSCRIBED', subscription: subscription.toJSON() })
            )
          );
      })
      .catch(() => undefined)
  );
});
